#include "ambient_harvester.h"
int harvester_compute(const HarvesterDensities*d,const HarvesterInstallation*i,const HarvesterLoad*l,HarvesterBudget*out){if(!d||!i||!l||!out)return -1;if(d->barometric_mw_per_m2<0||d->teg_uw_per_cm2<0||d->radiative_uw_per_cm2<0||d->piezo_uw_per_cm2<0||i->barometric_m2<0||i->teg_cm2<0||i->radiative_cm2<0||i->piezo_cm2<0||l->idle_power_w<0||l->useful_load_w<0)return -2;double h=d->barometric_mw_per_m2*1e-3*i->barometric_m2+d->teg_uw_per_cm2*1e-6*i->teg_cm2+d->radiative_uw_per_cm2*1e-6*i->radiative_cm2+d->piezo_uw_per_cm2*1e-6*i->piezo_cm2;double r=l->idle_power_w+l->useful_load_w;out->harvested_w=h;out->self_sustaining=h>=l->idle_power_w;out->can_power_load=h>=r;out->coverage_ratio=r>0?h/r:0;return 0;}
int harvester_emit_receipt(const HarvesterBudget*b,ibare_u8 out[32]){if(!b||!out)return -1;ibare_u8 buf[32];const double f[4]={b->harvested_w,b->self_sustaining,b->can_power_load,b->coverage_ratio};for(int i=0;i<4;i++){const ibare_u8*p=(const ibare_u8*)&f[i];for(int j=0;j<8;j++)buf[i*8+j]=p[j];}IBARE_SHA256_CTX c;ibare_sha256_init(&c);ibare_sha256_update(&c,buf,sizeof buf);ibare_sha256_final(&c,out);return 0;}
